"use strict";
// Makes the extension's generated files from scripts/protect.js and
// extension/core.js: extension/realm.js, the script every frame runs, and
// extension/bits/<n>.js, the files the state is told by (see filesFor in
// core.js). Run after tools/extract_from_ios.py changes scripts/protect.js:
//   node tools/build-extension.js
// With --pack <version>, it also writes dist/Noor-Edge-<version>.zip, the
// extension at that version, with a mark of its own for the replacements'
// source (protect.js's "noor lookalike"), so a page can't test for the
// mark this repository shows.
const crypto = require("crypto");
const fs = require("fs");
const path = require("path");
const zlib = require("zlib");
const { configFrom, BIT_COUNT } = require("../extension/core");

const root = path.join(__dirname, "..");
const extension = path.join(root, "extension");

/// The bits' files leave their numbers here, which realm.js takes away
/// before any of the page's scripts can run.
const BITS = "__noorBits";

const realmScript = (protectSource) => `// Generated by tools/build-extension.js from scripts/protect.js and
// extension/core.js. Don't edit by hand; rerun the tool.
//
// The browser runs this in every frame before the page's own scripts, after
// the files of the bits set (see filesFor in core.js), which tell it the
// state: it runs protect.js's protectPage with the seeds they give, in the
// page's own world, as the iPhone app runs it in Safari's pages.
(() => {
"use strict";
let bits = [];
try {
  bits = globalThis.${BITS} || [];
  delete globalThis.${BITS};
} catch (e) {}
// Only sites are protected, not the browser's own pages or extensions'.
if (!/^(https?|file|data|blob|about):$/.test(location.protocol)) return;
// A window a page opens starts as an empty page (about:blank) of its
// opener's origin, which the opener's copy of the protection protects as
// window.open returns it, and keeps its window, with the protection in it,
// when it goes on to a page of that origin. That page's copy leaves it as it
// is (it would add noise to the noise): its toString() hides the mark here,
// as only a protected window's does.
try {
  if (Function.prototype.toString.call(function () { /* noor lookalike */ }).indexOf("noor lookalike") === -1) return;
} catch (e) {}
const configFrom = ${configFrom.toString()};
const config = configFrom(bits);
${protectSource}
try {
  protectPage(window, config);
} catch (e) {}
})();
`;

/// A bit's file: its number, for realm.js.
const bitScript = (n) => `(globalThis.${BITS} || (globalThis.${BITS} = [])).push(${n});\n`;

/// protect.js keys a window's noise on its top page's site; an empty page
/// with no site of its own (a window a page opens, as window.open returns
/// it, which keeps its window when it goes on to a page of its origin) is
/// keyed here on its origin's site, as that page will be, and as its opener
/// is, instead of on no site at all.
const HOST_LAST = '      try { return window.location.hostname; } catch (e) { return ""; }\n';
const HOST_ORIGIN = '      try { const origin = window.origin; if (!window.location.hostname && origin && origin !== "null") return new window.URL(origin).hostname; } catch (e) {}\n';

/// protect.js as the extension runs it.
const protectForExtension = (text) => {
  if (text.split(HOST_LAST).length !== 2) {
    throw new Error("protect.js: the host's last fallback has changed; update tools/build-extension.js");
  }
  return text.replace("module.exports = protectPage;", "").replace(HOST_LAST, HOST_ORIGIN + HOST_LAST);
};

/// The generated files, by their path in the extension.
const generated = () => {
  // Read as LF, whatever a checkout made of it.
  const protect = protectForExtension(fs.readFileSync(path.join(root, "scripts", "protect.js"), "utf8").replace(/\r\n/g, "\n"));
  const files = { "realm.js": realmScript(protect) };
  for (let n = 0; n < BIT_COUNT; n++) {
    files[`bits/${n}.js`] = bitScript(n);
  }
  return files;
};

// MARK: - Zip

const CRC = (() => {
  if (typeof zlib.crc32 === "function") return (data) => zlib.crc32(data) >>> 0;
  const table = new Uint32Array(256).map((_, n) => {
    let c = n;
    for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
    return c >>> 0;
  });
  return (data) => {
    let c = 0xffffffff;
    for (const byte of data) c = table[(c ^ byte) & 0xff] ^ (c >>> 8);
    return (c ^ 0xffffffff) >>> 0;
  };
})();

/// A zip of `entries` ([name, Buffer]), deflated, as a Buffer.
const zip = (entries) => {
  const locals = [];
  const centrals = [];
  let offset = 0;
  for (const [name, data] of entries) {
    const nameBytes = Buffer.from(name, "utf8");
    const packed = zlib.deflateRawSync(data, { level: 9 });
    const crc = CRC(data);
    const local = Buffer.alloc(30);
    local.writeUInt32LE(0x04034b50, 0);
    local.writeUInt16LE(20, 4);
    local.writeUInt16LE(0x0800, 6);
    local.writeUInt16LE(8, 8);
    local.writeUInt32LE(0x00210000, 10);
    local.writeUInt32LE(crc, 14);
    local.writeUInt32LE(packed.length, 18);
    local.writeUInt32LE(data.length, 22);
    local.writeUInt16LE(nameBytes.length, 26);
    local.writeUInt16LE(0, 28);
    locals.push(local, nameBytes, packed);
    const central = Buffer.alloc(46);
    central.writeUInt32LE(0x02014b50, 0);
    central.writeUInt16LE(20, 4);
    central.writeUInt16LE(20, 6);
    central.writeUInt16LE(0x0800, 8);
    central.writeUInt16LE(8, 10);
    central.writeUInt32LE(0x00210000, 12);
    central.writeUInt32LE(crc, 16);
    central.writeUInt32LE(packed.length, 20);
    central.writeUInt32LE(data.length, 24);
    central.writeUInt16LE(nameBytes.length, 28);
    central.writeUInt32LE(offset, 42);
    centrals.push(central, nameBytes);
    offset += local.length + nameBytes.length + packed.length;
  }
  const centralSize = centrals.reduce((size, part) => size + part.length, 0);
  const end = Buffer.alloc(22);
  end.writeUInt32LE(0x06054b50, 0);
  end.writeUInt16LE(entries.length, 8);
  end.writeUInt16LE(entries.length, 10);
  end.writeUInt32LE(centralSize, 12);
  end.writeUInt32LE(offset, 16);
  return Buffer.concat([...locals, ...centrals, end]);
};

/// Every file of the extension, by its path in it, sorted.
const extensionFiles = (dir = extension, prefix = "") => fs.readdirSync(dir, { withFileTypes: true })
  .flatMap((entry) => (entry.isDirectory()
    ? extensionFiles(path.join(dir, entry.name), `${prefix}${entry.name}/`)
    : [`${prefix}${entry.name}`]))
  .sort();

/// The extension at `version`, zipped, with a mark of its own.
const pack = (version) => {
  if (!/^\d+(\.\d+){0,3}$/.test(version)) {
    throw new Error(`Not an extension version: ${version}`);
  }
  const mark = crypto.randomBytes(8).toString("hex");
  const entries = extensionFiles().map((name) => {
    let data = fs.readFileSync(path.join(extension, name));
    if (name === "manifest.json") {
      const manifest = JSON.parse(data.toString("utf8"));
      manifest.version = version;
      data = Buffer.from(`${JSON.stringify(manifest, null, 2)}\n`);
    } else if (name === "realm.js") {
      data = Buffer.from(data.toString("utf8").split("noor lookalike").join(mark));
    }
    return [name, data];
  });
  const out = path.join(root, "dist", `Noor-Edge-${version}.zip`);
  fs.mkdirSync(path.dirname(out), { recursive: true });
  fs.writeFileSync(out, zip(entries));
  return out;
};

if (require.main === module) {
  const files = generated();
  fs.rmSync(path.join(extension, "bits"), { recursive: true, force: true });
  fs.mkdirSync(path.join(extension, "bits"));
  for (const [name, text] of Object.entries(files)) {
    fs.writeFileSync(path.join(extension, name), text);
  }
  console.log(`wrote extension/realm.js and ${BIT_COUNT} bit files`);
  const at = process.argv.indexOf("--pack");
  if (at !== -1) {
    console.log(`wrote ${pack(process.argv[at + 1] || "")}`);
  }
}

module.exports = { generated, realmScript, bitScript, protectForExtension, zip, pack, extensionFiles, BITS };
